//! Durable vector check for `core/src/zip2005.rs` against the PUBLISHED ZIP 2005
//! `use_qsk = true` FVK-derivation vectors.
//!
//! Source of the vectors (`fixtures/zip2005_use_qsk.json`): ZcashFoundation/frost-tools
//! PR #610 (`test/zip2005-use-qsk-vectors`, zafe-cash fork, commit
//! `038204d4ff1f58042c54ce55be02336c77e703c6`), file
//! `zcash-sign/tests/fixtures/zip2005_use_qsk.json`. Generated by zafe-core; the PR notes
//! these are not yet OFFICIAL vectors, which is exactly why ZF frost issue #1094 asks for
//! the derivation to be reviewed. This test pins Loki's implementation to those vectors so
//! any drift in `zip2005.rs` fails CI.
//!
//! Each vector supplies `(sk, ak)` and the derived 96-byte Orchard FVK. We feed the same
//! `(ak, sk)` into Loki's `frost_viewing_key` and assert the full FVK byte-for-byte.

use loki_poc::zip2005::frost_viewing_key;
use serde_json::Value;

const VECTORS: &str = include_str!("fixtures/zip2005_use_qsk.json");

fn bytes32(v: &Value, name: &str) -> [u8; 32] {
    hex::decode(v[name].as_str().unwrap())
        .unwrap()
        .try_into()
        .unwrap()
}

#[test]
fn zip2005_matches_published_use_qsk_vectors() {
    let data: Value = serde_json::from_str(VECTORS).unwrap();
    // The blake3 derive-key context is part of the derivation; pin it to the exact
    // string hard-coded in core/src/zip2005.rs (`QK_CONTEXT`).
    assert_eq!(data["qk_context"], "Zcash ZIP 2005 qk-derivation v1");

    let vectors = data["vectors"].as_array().unwrap();
    assert_eq!(vectors.len(), 8, "expected the 8 published vectors");

    for (i, v) in vectors.iter().enumerate() {
        let ak = bytes32(v, "ak");
        let sk = bytes32(v, "sk");
        let want_fvk = hex::decode(v["fvk"].as_str().unwrap()).unwrap();

        let fvk = frost_viewing_key(&ak, &sk).expect("valid FVK");
        let got = fvk.to_bytes();

        assert_eq!(hex::encode(got), hex::encode(&want_fvk), "vector {i}: FVK");
        // Structural invariants of the use_qsk FVK = ak || nk || rivk.
        assert_eq!(&got[..32], &ak, "vector {i}: ak preserved");
        assert_eq!(&got[32..64], bytes32(v, "nk"), "vector {i}: nk");
        assert_eq!(&got[64..96], bytes32(v, "rivk_ext"), "vector {i}: rivk");
    }
}
